public async Task<int> PlaceOrderAsync(PlaceOrderDto dto, CancellationToken ct)
{
    var stock = await _db.Products.SingleAsync(p => p.Id == dto.ProductId, ct);
    if (stock.Available < dto.Quantity) throw new DomainRuleException("insufficient stock");
    stock.Available -= dto.Quantity;
    var order = new Order { ProductId = dto.ProductId, Quantity = dto.Quantity };
    _db.Orders.Add(order);
    await _db.SaveChangesAsync(ct);       // one implicit transaction for the whole script
    return order.Id;
}

